import java.util.*;import java.io.*;
class OrganicMaterialsTest {
 public static void main(String[]args)throws Exception{int n=256;var e=new EnvironmentMap(new float[n*n]);e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];e.snow=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*n+x;e.height[i]=x<80?90:90+(x-80)*2.5f;e.snow[i]=x>180?.7f:0;if(z>=115&&z<=123&&x<80){e.height[i]=85;e.water[i]=89;e.river[i]=1;}}e.trees=List.of(new TreeLibrary.Placement(0,40,45,0));var node=new TerrainGraph.Node(1,TerrainGraph.Type.ORGANIC_MATERIALS,0,0);node.values.put("forestFloor",.3);float[] old=e.height.clone(),water=e.water.clone();var out=OrganicMaterials.apply(node,e,n,n,62,71,0,0,()->false);var again=OrganicMaterials.apply(node,e,n,n,62,71,0,0,()->false);if(!Arrays.equals(old,out.height)||!Arrays.equals(water,out.water)||!Arrays.equals(out.material,again.material))throw new AssertionError("Materials change geography or are nondeterministic");boolean forest=false,rock=false;for(int i=0;i<n*n;i++){if(out.material[i]>=14&&out.material[i]<=16)forest=true;if(out.material[i]==3||out.material[i]==12||out.material[i]>=17)rock=true;if(e.snow[i]>0&&out.snow[i]>=e.snow[i])throw new AssertionError("Steep rock holds full snow blanket");}if(!forest||!rock)throw new AssertionError("Missing forest/rock palette");for(int m=14;m<=18;m++){int id=ExportBlocks.block(100,m,62,0,0,0,100,5);String name=ExportBlocks.state(id).name();if(!name.startsWith("minecraft:"))throw new AssertionError("Invalid state");if(ExportBlocks.block(100,m,62,0,0,0,m>=17?51:94,5)!=3)throw new AssertionError("Missing stone substrate");if(m<=16&&ExportBlocks.block(100,m,62,0,0,0,99,5)!=4)throw new AssertionError("Soil surface painted through underground");}var w=new TerraForge.World(32,62,71);Arrays.fill(w.height,100);w.environment.material=new byte[1024];for(int z=0;z<32;z++)for(int x=0;x<32;x++)w.environment.material[z*32+x]=(byte)(14+x%5);String chunk=new String(TerraForge.chunk(w,0,0),java.nio.charset.StandardCharsets.ISO_8859_1);for(String name:new String[]{"podzol","rooted_dirt","moss_block","diorite","granite"})if(!chunk.contains("minecraft:"+name))throw new AssertionError("Actual chunk missing "+name);var bytes=new ByteArrayOutputStream();out.write(new DataOutputStream(bytes));var loaded=EnvironmentMap.read(new DataInputStream(new ByteArrayInputStream(bytes.toByteArray())),old,true);if(!Arrays.equals(out.material,loaded.material))throw new AssertionError("New materials lost on save");System.out.println("PASS: organic forest/rock deposits, deterministic placement, geography preserved, steep snow retreat, layered block states and material save round-trip");}
}
